import{_ as t,C as l,o,c as i,a3 as d,b as p,w as c,a as s,E as r,a4 as n}from"./chunks/framework.d6OaePA7.js";const N=JSON.parse('{"title":"公网访问DDNS+IPV6","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://scattter.github.io/pages/explore/others/%E5%85%AC%E7%BD%91%E8%AE%BF%E9%97%AE(DDNS+IPV6).html"}]]},"headers":[],"relativePath":"pages/explore/others/公网访问(DDNS+IPV6).md","filePath":"pages/explore/others/公网访问(DDNS+IPV6).md","lastUpdated":1693917276000}'),g={name:"pages/explore/others/公网访问(DDNS+IPV6).md"};function m(h,e,b,_,P,u){const a=l("Mermaid");return o(),i("div",null,[e[1]||(e[1]=d('<h1 id="公网访问ddns-ipv6" tabindex="-1">公网访问<code>DDNS</code>+<code>IPV6</code> <a class="header-anchor" href="#公网访问ddns-ipv6" aria-label="Permalink to &quot;公网访问`DDNS`+`IPV6`&quot;">​</a></h1><blockquote><p>近期由于自己搭建了一个类似<code>Nas</code> 的软件, 所以有外网访问家中路由(服务器)的需求. 最快捷的方法就是有一个公网ip, 但是现在<code>IPV4</code>地址有这么稀缺, 所以这一方案就只能暂时pass. 同时, <code>Zerotier</code> 和<code>Tailscale</code> 的速度也依赖于隧道两端服务器, 不够稳定, 且速度也远远达不到直连的效果, 每次登陆都要开代理, 所以就需要寻找其他方案.</p><p><code>IPV6</code> 是新一代的ip地址协议, 其为了解决<code>IPV4</code> 地址不够使用的问题而诞生, 数量级相比于<code>IPV4</code> 是N多倍, 所以几乎每个路由都有一个<code>IPV6</code> 地址. 因此, 我们可以借用<code>IPV6</code>进行公网访问.</p></blockquote><p>为了能够实现公网访问, 本文会涉及到方面, 大致流程如下所示:</p>',3)),(o(),p(n,null,{default:c(()=>[r(a,{id:"mermaid-14",graph:"flowchart%20LR%0A%09%E8%B7%AF%E7%94%B1%E6%8B%A8%E5%8F%B7%20--%3E%20%E8%8E%B7%E5%8F%96IPV6%E5%9C%B0%E5%9D%80%20--%3E%20%E8%B4%AD%E4%B9%B0%E5%9F%9F%E5%90%8D%E7%BB%91%E5%AE%9ADNS%20--%3E%20NPM%E5%8F%8D%E5%90%91%E4%BB%A3%E7%90%86%20--%3E%20SSL%E8%AF%81%E4%B9%A6%0A"})]),fallback:c(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=d('<p>后续也主要是基于这个步骤来描述.</p><h2 id="_1-光猫桥接" tabindex="-1">1. 光猫桥接 <a class="header-anchor" href="#_1-光猫桥接" aria-label="Permalink to &quot;1. 光猫桥接&quot;">​</a></h2><p>因为<code>IPV6</code>地址很长, 同时又不好记忆, 所以在日常网页访问过程中直接使用<code>IPV6</code>地址是不现实的, 这就需要用到域名来映射<code>IPV6</code>地址, 进行实现快捷访问, 这就是<code>DNS</code> ( Domain Name System).</p><p>此外, 虽然每一台路由器都有一个公网<code>IPV6</code>地址, 但是运营商每隔一段时间会重置我们的<code>IPV6</code>地址, 所以我们要动态的更新我们的域名和<code>IPV6</code>地址的映射关系, 也就是<code>DDNS</code> (Dynamatic Domain Name System).</p><p>一般来讲, 我们自己配的路由器性能会更好一点, 所以为了更好的进行<code>DDNS</code>, 发挥路由器的效果, 我们首先需要选择<code>DDNS</code>适配不错的路由器, 然后使用路由器进行拨号, 光猫桥接, 借助路由器的<code>DDNS</code>将自己的域名和<code>IPV6</code>地址进行一个动态更新.</p><p>在这一步, 我们先进行光猫桥接, 路由器拨号的操作.</p><p>首先需要进入光猫的后台, 一般为<code>192.168.1.1</code>, 同时我们需要根据光猫的型号去网上查找超管密码, 没有超管密码改不了光猫的连接方式.</p><p>以我现在租房子移动给的<code>ZN-R173G</code> 为例:</p><p>光猫账号密码为: <code>CMCCAdmin</code> 和 <code>aDm8H%MdA</code></p><p>除此之外, 我们还需要自己宽带的账号和密码, 这两个可以打运营商电话获取.</p><h3 id="_1-1-后台信息" tabindex="-1">1.1 后台信息 <a class="header-anchor" href="#_1-1-后台信息" aria-label="Permalink to &quot;1.1 后台信息&quot;">​</a></h3><p>进入路由器后台后, 我们可以看到光猫的一些连接信息, 其中表格中第一行 <code>4_INTERNET_R_VID_4031</code> 就是我们光猫和互联网连接使用的通道, 记住最后的<code>VID: 4031</code> , 后面我们新增桥接模式的时候要用到.</p><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20230820202156555.png" alt="image-20230820202156555"></p><p>随后我们进入网络栏, 找到这个连接, 将所有的配置都记录下来.</p><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20230820202331325.png" alt="image-20230820202331325"></p><h3 id="_1-2-光猫设置" tabindex="-1">1.2 光猫设置 <a class="header-anchor" href="#_1-2-光猫设置" aria-label="Permalink to &quot;1.2 光猫设置&quot;">​</a></h3><p>进入网络栏后, 找到上面说的连接, 进行删除, 然后创建一个新的连接.</p><p>在出现的配置中, 选择模式为桥接, 类似下面的图, 不过这里需要把<code>Vlan ID</code> 换为上一小节记录的<code>VID</code>, 如果是<code>4031</code> , 那么就填<code>4031</code> . 其他和之前保持一致就行, 如下:</p><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20230820202551416.png" alt="image-20230820202551416"></p><h3 id="_1-3-路由器拨号" tabindex="-1">1.3 路由器拨号 <a class="header-anchor" href="#_1-3-路由器拨号" aria-label="Permalink to &quot;1.3 路由器拨号&quot;">​</a></h3><p>进入路由器的配置页面, 我这里暂时使用斐讯k2为例子, 修改保存后路由器自动重启, 此时就是路由器拨号了.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>有些地方可能需要将<strong>光猫的mac地址复制下来</strong>, 在下面的高级设置里面设置下, 否则移动那边不响应.</p></div><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20230820204144491.png" alt="image-20230820204144491"></p><h2 id="_2-获取ipv6地址" tabindex="-1">2. 获取IPV6地址 <a class="header-anchor" href="#_2-获取ipv6地址" aria-label="Permalink to &quot;2. 获取IPV6地址&quot;">​</a></h2><p>因为之前的斐讯k2不支持<code>IPV6</code> , 拨号后也获取不到地址, 所以只能购入新的设备了.现在买的是<code>Tplink 6088</code> , 本来以为配置后台会好一点, 然后能用它自带的<code>DDNS</code>, 但是用了后发现其实很鸡肋, 性价不高, 如果没有<code>2.5G</code> 需求, 可以考虑其他便宜一些的路由器.</p><h3 id="_2-1-路由设置和连接" tabindex="-1">2.1 路由设置和连接 <a class="header-anchor" href="#_2-1-路由设置和连接" aria-label="Permalink to &quot;2.1 路由设置和连接&quot;">​</a></h3><p>重复上一节路由器拨号部分, <code>6088</code> 的拨号设置页面如下所示:</p><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20230826224036003.png" alt="image-20230826224036003"></p><p>也是和斐讯一样设置账号就行了.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>这里有需要注意的一点, 路由器需要支持关闭<code>IPV6</code>防火墙, 不然外网访问不了. 具体位置如下</p></div><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20230826224245327.png" alt="image-20230826224245327"></p><h3 id="_2-2-查询地址" tabindex="-1">2.2 查询地址 <a class="header-anchor" href="#_2-2-查询地址" aria-label="Permalink to &quot;2.2 查询地址&quot;">​</a></h3><p>这一步设置好之后, 连上主机(服务器), 获取<code>IPV6</code>地址, 一个比较简单的方式是使用命令行<code>curl 6.ipw.cn</code> 去获取<code>IPV6</code>地址, 更多的命令行可以看<a href="https://ipw.cn/%60IPV6%60/" target="_blank" rel="noreferrer">这里</a>. 另一种就是使用服务器自带的ip命令去查询了, 一般移动的前缀是<code>2409</code> , 其他运营商的可以在网上查下.</p><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20230827003942437.png" alt="image-20230827003942437"></p><h2 id="_3-域名购买与dns和ddns" tabindex="-1">3. 域名购买与DNS和<code>DDNS</code> <a class="header-anchor" href="#_3-域名购买与dns和ddns" aria-label="Permalink to &quot;3. 域名购买与DNS和`DDNS`&quot;">​</a></h2><h3 id="_3-1-域名购买" tabindex="-1">3.1 域名购买 <a class="header-anchor" href="#_3-1-域名购买" aria-label="Permalink to &quot;3.1 域名购买&quot;">​</a></h3><p>这里分为免费和付费两种.</p><ul><li>免费域名</li></ul><p>免费的域名可以自己查找一下, 我感觉比较好的是<code>dynv6</code> , 虽然只是二级域名, 但是他免费啊, 而且前期可以用来自己测试能否跑通, 跑通了就可以换为付费域名了.</p><ul><li>付费域名</li></ul><p>国内的一般都要进行备案, 不但麻烦还比较贵, 于是我把目标放到国外域名商. 很多国外的域名商卖的也贵, 正好有次看到有网友说<code>google domain</code> 上土耳其区域名便宜, 就上去看了下, 一个十年的域名最低只要200米(750土耳其币), 还能选<code>org</code> 这种后缀的域名, 可以说很值了. 如下(要先选择土耳其区)</p><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20230826233821880.png" alt="image-20230826233821880"></p><p>但是这里要注意两点, <code>google domain</code> 要求要有<strong>visa或者万事达信用卡</strong>, 不然没办法付款, 不支持<code>PayPal</code> ; 而且<code>google domain</code> 的域名服务可能要被其他公司收购了.</p><blockquote><p>我为了能购买, 专门申请了一张visa(当然我也是想简单混下卡圈, 这些信用卡的东西后面有时间再说)</p></blockquote><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20230826233533694.png" alt="image-20230826233533694"></p><h3 id="_3-2-dns配置" tabindex="-1">3.2 DNS配置 <a class="header-anchor" href="#_3-2-dns配置" aria-label="Permalink to &quot;3.2 DNS配置&quot;">​</a></h3><p>一般来讲, 你的域名在哪购买的, 就可以在哪进行<code>DNS</code> 配置, 但是开源工具对<code>google domain</code> 的 <code>dns</code> 服务支持没那么好, 所以我使用了支持情况比较好的<code>Cloudflare</code> , 上面添加站点后可以进行免费<code>DNS</code> . 从<code>google domain</code> 转移到<code>Cloudflare</code> 的流程如下:</p><ol><li>先在<code>Cloudflare</code>上添加自己的域名, 随后进入域名详情里面, 找到分配的服务器, 将其复制下来.</li></ol><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20230826234350632.png" alt="image-20230826234350632"></p><ol start="2"><li>其次在<code>google domain</code> 上选择使用自定义域名服务器, 将上一步的两个服务器地址粘贴在输入框即可.</li></ol><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20230826234258669.png" alt="image-20230826234258669"></p><p>这样我们就成功替换了<code>DNS</code> 服务商.</p><ol start="3"><li>回到<code>Cloudflare</code>上, 配置自己的<code>DNS</code></li></ol><p>在这里因为我们只有<code>IPV6</code>, 所以添加记录的时候选择类型为<code>AAAA</code> 就行, 然后在名称里面填上自己的域名(如<code>example.com</code> ), 后面填上自己的<code>IPV6</code>地址.</p><p>如果自己有一些子域名, 比如<code>home.example.com</code>, 或者<code>happy.example.com</code> 等, 我们就可以使用一个泛域名来进行解析, 也即新增类型<code>CNAME</code>, 名称填<code>*</code> , 其他内容不填即可.</p><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20230826234721602.png" alt="image-20230826234721602"></p><h3 id="_3-3-ddns-go部署" tabindex="-1">3.3 DDNS-GO部署 <a class="header-anchor" href="#_3-3-ddns-go部署" aria-label="Permalink to &quot;3.3 DDNS-GO部署&quot;">​</a></h3><p>这里的部署比较简单, 直接看项目地址或者网上搜索就行.下图就是主要的配置页面</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><ol><li><p>如果你的内网有两台机器<code>a</code> 和<code>b</code> , 你在机器<code>a</code> 上部署, 想在机器<code>b</code> 上打开配置页面, 那么就要先把机器<code>a</code> 上的<code>9876</code> 防火墙打开, 否则机器<code>b</code> 打不开配置页面.</p></li><li><p>这里<code>Cloudflare</code> 的<code>token</code> 是需要去手动创建的, 不等效于<code>global key</code>, 具体可以参考<a href="https://abigalefocus.medium.com/%E6%9E%B6%E7%AB%99%E7%AD%86%E8%A8%98-%E7%AE%A1%E7%90%86%60Cloudflare%60-api-tokens%E5%92%8Ckeys-1bd6ad24883e" target="_blank" rel="noreferrer">这里.</a></p></li><li><p>如果只有<code>IPV6</code>, 那么就把<code>IPV4</code>的关闭.</p></li></ol></div><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20230826232752360.png" alt="image-20230826232752360"></p><h2 id="_4-npm反向代理和ssl证书申请" tabindex="-1">4. NPM反向代理和SSL证书申请 <a class="header-anchor" href="#_4-npm反向代理和ssl证书申请" aria-label="Permalink to &quot;4. NPM反向代理和SSL证书申请&quot;">​</a></h2><p>在进行完上面三部分后, 其实我们就可以访问自己的服务器了, 当然前提是服务器上部署了相应的服务且打开了相应端口的防火墙. 连接形式为<code>xxx.example.com:9898</code></p><p>但是这样的话我们有一个端口部署了相应的服务就需要开一个防火墙, 此外每一次访问都是不安全连接, 有很大的风险, 因此我们就需要使用<code>NPM</code> (nginx proxy manage) 进行反向代理和SSL加密.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>这里反向代理的软件还有<code>lucky</code> 和 <code>NginxWebUI</code> , 前者还是挺好的, 内部集成了<code>DDNS</code> 和 <code>SSL</code> 证书申请, 全套链路, 但是最新的版本没有开源. 后者是配置页面感觉不是很好, <code>nginx</code> 的重启比较麻烦, 所以使用了<code>NPM</code> .</p></div><h3 id="_4-1-npm部署" tabindex="-1">4.1 NPM部署 <a class="header-anchor" href="#_4-1-npm部署" aria-label="Permalink to &quot;4.1 NPM部署&quot;">​</a></h3><p>这里的<code>NPM</code> 不是前端的<code>NPM</code> 包管理器, 是<code>nginx proxy manager</code> 的缩写. 其是一个可视化的<code>nginx</code> 工具, 用户在上面可以快速创建一个代理, 同时还能快捷申请<code>SSL证书</code> . 这样的话, 我们只需要开放一个端口, 然后使用二级域名, 加上<code>NPM</code> 的反向代理, <code>SSL</code> 的加密, 即可极大程度的降低外网访问的风险.</p><p>部署可以直接参考官方教程, 登录页面后让你改用户名和密码, 随后你就可以自己配置了. 这里可以直接参考b站的一个视频: <a href="https://www.bilibili.com/video/BV1Ws4y1A7Lk" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1Ws4y1A7Lk</a></p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>由于我们目前是在家庭宽带上进行服务器部署, 宽带运营商会直接屏蔽<code>80/443</code> 端口, 因此我们部署<code>NPM</code> 的时候需要将<code>80/443</code> 映射为其他开放端口(<code>docker-compose.yml</code> 文件需要更改为其他端口).</p></div><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20230827002455640.png" alt="image-20230827002455640"></p><h3 id="_4-2-证书申请" tabindex="-1">4.2 证书申请 <a class="header-anchor" href="#_4-2-证书申请" aria-label="Permalink to &quot;4.2 证书申请&quot;">​</a></h3><p>这里单独拿出来主要是因为如果使用家用宽带, 通过<code>NPM</code> 的专门<code>SSL</code> 申请页面很难申请到证书, 一直会报服务端错误, 这里有两种解决方案.</p><ol><li>在具体的反向代理里面为子域名单独申请, 这里是可以申请成功的.(比较推荐, 只是创建的时候稍微麻烦一点)</li><li>使用<code>NginxWebUI</code> 来申请证书, 然后再下载下来传到<code>NPM</code> 上.(不太推荐, 不支持自动刷新)</li></ol><p>经过上述配置后, 我们就可以使用<code>https</code> 来访问我们的网站了, 这里因为家用宽带443端口被屏蔽, 所以我们假设部署的时候使用<code>4443</code> 端口来映射, 那么访问地址就会类似于: <code>happy.example.com:4443</code> , 如下所示</p><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20230826223958216.png" alt="image-20230826223958216"></p><h2 id="_5-小结" tabindex="-1">5. 小结 <a class="header-anchor" href="#_5-小结" aria-label="Permalink to &quot;5. 小结&quot;">​</a></h2><p>本文到这里也就结束了, 从刚开始部署自己的小主机到现在断断续续有快一年了, 从刚开始的<code>Zerotier</code> 到<code>Tailscale</code> , 终于到现在可以通过域名直接访问了. 文中有有很多内容来自网上一些大佬的分享, 我才能把这些流程跑通, 原理搞明白, 希望以后自己也能在不断探索中在互联网上贡献一些技能和经验.</p>',76))])}const S=t(g,[["render",m]]);export{N as __pageData,S as default};
